import{_ as a}from"./chunks/console-rings.C4ZxRMHb.js";import{_ as o,o as t,c as r,a3 as s}from"./chunks/framework.DhF4LrUq.js";const n="/shipperdog/snapshot/screenshots/roles/console-rm-release-detail.png",f=JSON.parse('{"title":"Release Manager quickstart","description":"Quickstart for Release Managers — release creation, approvals, gates, ring promotion, staged rollout, and rollback, in the Console and the CLI.","frontmatter":{"description":"Quickstart for Release Managers — release creation, approvals, gates, ring promotion, staged rollout, and rollback, in the Console and the CLI."},"headers":[],"relativePath":"roles/release-manager.md","filePath":"roles/release-manager.md"}'),i={name:"roles/release-manager.md"};function l(h,e,d,p,c,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="release-manager-quickstart" tabindex="-1">Release Manager quickstart <a class="header-anchor" href="#release-manager-quickstart" aria-label="Permalink to &quot;Release Manager quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You take a build from &quot;it exists&quot; to &quot;it is in production&quot; — and back out again when it has to be. Your system role is <strong><code>RELEASE_MANAGER</code></strong>, and your primary surfaces are the Console&#39;s release dashboard plus the CLI, which drives the same operations from CI or your terminal. Release Managers own the release lifecycle: creating releases, steering them through approvals and gates, promoting them ring by ring, widening the rollout to more tenants, and rolling back when the numbers say so. If you also configure the governance those releases follow, that is the same role — you hold both; see <a href="#what-you-can-do">what you can do</a>. If you additionally own applications or administer the organization, work one track per session: the <a href="/shipperdog/snapshot/roles/app-owner">App Owner</a> and <a href="/shipperdog/snapshot/roles/org-admin">Organization Admin</a> guides cover those hats.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Run releases</strong> — create them, pick the version and targets, drive every lifecycle transition, and read everything about any release in the organization.</li><li><strong>Sign the final approval.</strong> The approval chain typically runs QA, Security, Compliance, and Product steps — and the last signature, the Release Manager&#39;s own release approval, is yours.</li><li><strong>Hold the two audited exceptions</strong> — overriding a failed or data-less quality gate, and proceeding past a policy hold. Both demand a written reason and both land in the audit trail: they are the exception records the trail exists for.</li><li><strong>Govern the pipeline</strong> — define environments, approval workflows, gate definitions, release rings, declarative release policies, and ABAC policies: the rules your releases mechanically answer to.</li><li><strong>Watch the numbers</strong> — read the release analytics every promotion decision rests on, and trigger a recompute when history needs repair.</li><li><strong>Work the feedback queue</strong> — triage reports alongside QA; open critical bugs are the metric your promotions answer to.</li><li><strong>Route notifications</strong> — decide which events reach which channels.</li></ul><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Sign in and read the dashboard.</strong> The pending-actions panel personalizes to you: the release approvals waiting on your signature and the failed gates you have authority to override. Each row deep-links to the release it acts on.</p></li><li><p><strong>Open the release waiting on you.</strong> The release dashboard is one screen per release: lifecycle actions offering exactly the legal next steps, the approvals round, the quality gates, distribution and targets, the promotion panel, and the frozen manifest. The screenshot shows a release waiting in <code>APPROVAL_PENDING</code> with the Release Manager step outstanding and both required gates passed.</p><p><img src="'+n+'" alt="The release dashboard as the Release Manager"></p></li><li><p><strong>Sign the release approval</strong> on the <strong>Approvals</strong> panel — or reject it with a reason. Your signature is recorded with your name and timestamp; the chain&#39;s progress is visible to everyone who can see the release.</p></li><li><p><strong>Check the gates.</strong> The <strong>Quality Gates</strong> panel shows each gate&#39;s state, the evidence behind it, and observed values against thresholds. If a gate failed and you decide to ship anyway, the override is right there — mandatory reason, permanently audited.</p></li><li><p><strong>Promote, one ring at a time.</strong> The promotion panel&#39;s precheck answers &quot;why can&#39;t I promote?&quot; before you ask: missing approvals, blocking gates, and policy holds each surface with their reason. Promotion widens the release to the next ring — the ladder your organization defined:</p><p><img src="'+a+'" alt="The rings editor"></p></li><li><p><strong>Know the exits.</strong> Staged rollout widens tenant targeting ring by ring; rollback takes a release out of distribution with a mandatory reason. Skim both how-tos now — <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout</a> and <a href="/shipperdog/snapshot/how-to/console/rollback">rollback</a> — so the first time you use them is not during an incident.</p></li><li><p><strong>From the terminal</strong>, the same operations ride the CLI: <code>shipperdog release create</code>, <code>release transition</code>, <code>release precheck</code>, <code>release promote</code>, and <code>release manifest</code> — the surface CI pipelines drive.</p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/concepts/release-lifecycle">the release lifecycle</a> — the state machine behind every button you will press</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a> and <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout</a></li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback analytics</a> — the metrics your promotion decisions answer to</li><li>[ ] How-tos as they land: <a href="/shipperdog/snapshot/how-to/console/releases">releases</a>, <a href="/shipperdog/snapshot/how-to/console/approvals">approvals</a>, <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a>, <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a>, <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout</a>, <a href="/shipperdog/snapshot/how-to/console/rollback">rollback</a></li><li>[ ] CLI depth for CI: the <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI reference</a></li></ul>',11)])])}const y=o(i,[["render",l]]);export{f as __pageData,y as default};
